import { bankRequest } from './client';
import { randomUUID } from 'node:crypto';
import { appDb } from '../db';
import { HttpError } from '../auth';
import type { Account, ActionResult, ToolContext, TransferInput } from '../types';
export async function authorizeTransfer(
  ctx: ToolContext,
  input: TransferInput,
): Promise<ActionResult | null> {
  const accounts = await bankRequest<Account[]>(ctx.userId, '/v1/accounts');
  if (!accounts.some((a) => a.id === input.fromAccountId))
    throw new HttpError(403, 'This account does not belong to this person.');
  if (input.fromAccountId === input.toAccountId)
    throw new HttpError(400, 'Source and destination must differ.');
  const db = appDb(), payload = JSON.stringify(input);
  if (ctx.approvalId) {
    const approval = db.prepare('SELECT * FROM approvals WHERE id=?').get(ctx.approvalId) as
      { user_id: string; intent_id: string; payload: string; expires_at: string; consumed_at: string | null } | undefined;
    if (!approval || approval.user_id !== ctx.userId || approval.intent_id !== ctx.intentId || approval.payload !== payload)
      throw new HttpError(403, 'This proposal does not authorize this transfer.');
    if (!approval.consumed_at && approval.expires_at <= new Date().toISOString())
      throw new HttpError(410, 'This proposal expired. Request a new proposal.');
    return null;
  }
  const approval = db.transaction(() => {
    const now = new Date().toISOString();
    const existing = db.prepare('SELECT id,payload,expires_at FROM approvals WHERE user_id=? AND intent_id=? AND consumed_at IS NULL AND expires_at>? ORDER BY expires_at DESC LIMIT 1')
      .get(ctx.userId, ctx.intentId, now) as { id: string; payload: string; expires_at: string } | undefined;
    if (existing) return existing;
    const id = randomUUID(), expires_at = new Date(Date.now() + 10 * 60 * 1000).toISOString();
    db.prepare('INSERT INTO approvals VALUES(?,?,?,?,?,NULL)').run(id, ctx.userId, ctx.intentId, payload, expires_at);
    db.prepare('UPDATE intents SET status=? WHERE id=? AND bank_reference IS NULL').run('requires_confirmation', ctx.intentId);
    return { id, payload, expires_at };
  })();
  return { status: 'requires_confirmation', intentId: ctx.intentId,
    approval: { id: approval.id, payload: JSON.parse(approval.payload), expiresAt: approval.expires_at } };
}
import { bankRequest, BankError } from './client';
import type { Operation, ToolContext, TransferInput } from '../types';
export class UnknownTransferError extends Error {}
async function reconcile(ctx: ToolContext, reference: string): Promise<Operation | null> {
  try {
    return await bankRequest<Operation>(ctx.userId, `/v1/operations/${encodeURIComponent(reference)}`);
  } catch (error) {
    if (error instanceof BankError && error.status === 404) return null;
    throw new UnknownTransferError('The bank could not verify the transfer. Retry this same intent to check its status.');
  }
}
export async function dispatchTransfer(ctx: ToolContext, input: TransferInput, reference: string, existingReference: boolean): Promise<Operation> {
  if (existingReference) {
    const operation = await reconcile(ctx, reference);
    if (operation) return operation;
  }
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      return await bankRequest<Operation>(ctx.userId, '/v1/transfers', 'POST', {
        ...input,
        reference,
      });
    } catch (e) {
      if (e instanceof BankError && e.status < 500) throw e;
      const operation = await reconcile(ctx, reference);
      if (operation) return operation;
      if (attempt === 1) throw new UnknownTransferError('The transfer is not yet verified. Retry this same intent; do not create another transfer.');
    }
  }
  throw new UnknownTransferError('The transfer is not yet verified.');
}
import { appDb } from '../db';
import { person } from '../people';
import { HttpError } from '../auth';
import { bankRequest } from '../banking/client';
import { buildCaseCopilot } from './copilot';
import type { Account, Operation } from '../types';
export type CaseMessage = { id: string; role: string; content: string; created_at: string; run_id: string | null };
export type CaseEvent = { id: string; kind: string; data: Record<string, unknown>; created_at: string; run_id: string };
export type CaseIntent = { id: string; status: string; payload: Record<string, unknown>; bank_reference: string | null; operation_id: string | null; error: string | null; created_at: string };
export type CaseEvidence = {
  incident: { id: string; user_id: string; conversation_id: string; summary: string; status: string; created_at: string };
  history: CaseMessage[];
  events: CaseEvent[];
  intents: CaseIntent[];
  bank: { accounts: Account[]; operations: Operation[] } | null;
  bankError: string | null;
  bankObservedAt: string;
  evidenceGaps: string[];
};
function parseRecord(raw: string): Record<string, unknown> {
  try {
    const value = JSON.parse(raw);
    return value !== null && typeof value === 'object' && !Array.isArray(value)
      ? value : { evidenceError: 'Stored evidence is not an object.' };
  } catch { return { evidenceError: 'Stored evidence could not be decoded.' }; }
}
export async function caseDetail(operatorId: string, id: string) {
  if (person(operatorId)?.role !== 'operator') throw new HttpError(403, 'Operator role required.');
  const db = appDb();
  const incident = db.prepare('SELECT * FROM incidents WHERE id=?').get(id) as CaseEvidence['incident'] | undefined;
  if (!incident) throw new HttpError(404, 'Case not found.');
  const history = db.prepare('SELECT * FROM messages WHERE conversation_id=? ORDER BY created_at,rowid')
    .all(incident.conversation_id) as CaseMessage[];
  const events = (db.prepare('SELECT * FROM events WHERE conversation_id=? AND user_id=? ORDER BY created_at,rowid')
    .all(incident.conversation_id, incident.user_id) as (Omit<CaseEvent, 'data'> & { data: string })[])
    .map((event) => ({ ...event, data: parseRecord(event.data) }));
  const intents = (db.prepare('SELECT * FROM intents WHERE conversation_id=? AND user_id=? ORDER BY created_at,rowid')
    .all(incident.conversation_id, incident.user_id) as (Omit<CaseIntent, 'payload'> & { payload: string })[])
    .map((intent) => ({ ...intent, payload: parseRecord(intent.payload) }));
  let bank: CaseEvidence['bank'] = null;
  let bankError: string | null = null;
  try {
    bank = await bankRequest<NonNullable<CaseEvidence['bank']>>(operatorId,
      `/v1/operator/customer?id=${encodeURIComponent(incident.user_id)}`);
  } catch (error) { bankError = error instanceof Error ? error.message : 'Bank evidence unavailable.'; }
  const evidenceGaps: string[] = [];
  if (!history.length) evidenceGaps.push('No conversation messages were recorded.');
  if (!events.length) evidenceGaps.push('No tool events were recorded. Historical bank effects cannot be inferred from the conversation.');
  if (events.some((event) => event.data.evidenceError ||
      (event.kind.startsWith('tool.') && !('arguments' in event.data))))
    evidenceGaps.push('Some historical events lack arguments or readable evidence; their details cannot be reconstructed.');
  if (!intents.length) evidenceGaps.push('No transfer intents were recorded for this conversation.');
  if (!bank) evidenceGaps.push('The bank snapshot is unavailable; transfer outcomes remain unverified.');
  const evidence: CaseEvidence = { incident, history, events, intents, bank, bankError,
    bankObservedAt: new Date().toISOString(), evidenceGaps };
  return {
    ...evidence,
    customer: person(incident.user_id),
    lastMessage: history.at(-1) ?? null,
    copilot: buildCaseCopilot(evidence),
  };
}
