    Array.from({ length: 5 }, () => transferMoney(approved, input)),
  );
  assert.ok(results.every((result) => result.status === 'completed'));
  assert.equal(new Set(results.map((result) => (result.operation as any).id)).size, 1);
  closeAppDb();
